// Package store is the hub's PostgreSQL access: a pgx pool built from a DSN file
// and the typed queries generated by sqlc (internal/store/dbgen).
//
// The pool connects as the DML-only sakuraops_app role. It never runs DDL; schema
// changes belong to cmd/sakuraops-migrate.
package store

import (
	"context"
	"errors"
	"fmt"
	"net"
	"time"

	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/MiyazakiTakara/sakura-ops/internal/dsnfile"
	"github.com/MiyazakiTakara/sakura-ops/internal/store/dbgen"
)

// Schema is the PostgreSQL schema that holds every SakuraOps object.
const Schema = "sakuraops"

// ErrInvalidDSN is returned for any unparsable database URL. It deliberately
// carries no detail: parser messages can echo parts of the URL.
var ErrInvalidDSN = errors.New("invalid database URL")

// Options tune the pool. Zero values select the defaults noted below.
type Options struct {
	ApplicationName  string        // default "sakuraops-hub"
	ConnectTimeout   time.Duration // default 5s
	StatementTimeout time.Duration // server-side per statement, default 15s
	MaxConns         int32         // default 10
}

// Store wraps the pool and the generated queries.
type Store struct {
	pool *pgxpool.Pool
	q    *dbgen.Queries
}

// ConfigFromDSN builds the pool config from a database URL. Pure and offline,
// so it is unit-testable.
func ConfigFromDSN(dsn string, o Options) (*pgxpool.Config, error) {
	cfg, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		return nil, ErrInvalidDSN
	}
	if o.ApplicationName == "" {
		o.ApplicationName = "sakuraops-hub"
	}
	if o.ConnectTimeout <= 0 {
		o.ConnectTimeout = 5 * time.Second
	}
	if o.StatementTimeout <= 0 {
		o.StatementTimeout = 15 * time.Second
	}
	if o.MaxConns <= 0 {
		o.MaxConns = 10
	}
	cfg.ConnConfig.ConnectTimeout = o.ConnectTimeout
	cfg.MaxConns = o.MaxConns
	cfg.MinConns = 0 // lazy: the hub starts and reports /readyz 503 while the database is down
	cfg.HealthCheckPeriod = 30 * time.Second
	cfg.MaxConnLifetime = time.Hour
	rp := cfg.ConnConfig.RuntimeParams
	rp["application_name"] = o.ApplicationName
	rp["search_path"] = Schema
	rp["statement_timeout"] = fmt.Sprintf("%d", o.StatementTimeout.Milliseconds())
	rp["idle_in_transaction_session_timeout"] = "30000"
	return cfg, nil
}

// OpenFromFile reads the DSN file, builds the pool and returns warnings for the
// caller to log. The pool connects lazily; use SchemaVersion to probe.
func OpenFromFile(ctx context.Context, path string, o Options) (*Store, []string, error) {
	res, err := dsnfile.Read(path)
	if err != nil {
		return nil, nil, err
	}
	cfg, err := ConfigFromDSN(res.URL, o)
	if err != nil {
		return nil, nil, err
	}
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, nil, fmt.Errorf("create pool: %s", Describe(err))
	}
	return &Store{pool: pool, q: dbgen.New(pool)}, res.Warnings, nil
}

// Close releases the pool.
func (s *Store) Close() { s.pool.Close() }

// SchemaVersion returns the applied migration version, or 0 when the schema
// function does not exist yet (database not migrated).
func (s *Store) SchemaVersion(ctx context.Context) (int64, error) {
	v, err := s.q.SchemaVersion(ctx)
	if err != nil {
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && (pgErr.Code == "42883" || pgErr.Code == "42P01" || pgErr.Code == "3F000") {
			// undefined_function, undefined_table, invalid_schema_name
			return 0, nil
		}
		return 0, err
	}
	return v, nil
}

// InstanceSettings is the singleton configuration row.
type InstanceSettings struct {
	InstanceName string
	Timezone     string
	Revision     int64
	UpdatedAt    time.Time
}

// GetInstanceSettings reads the singleton row.
func (s *Store) GetInstanceSettings(ctx context.Context) (InstanceSettings, error) {
	r, err := s.q.GetInstanceSettings(ctx)
	if err != nil {
		return InstanceSettings{}, err
	}
	return InstanceSettings{
		InstanceName: r.InstanceName,
		Timezone:     r.Timezone,
		Revision:     r.Revision,
		UpdatedAt:    r.UpdatedAt.Time,
	}, nil
}

// Describe returns a short classification of a database error that is safe to
// log and never contains the URL, host, user or server message text.
func Describe(err error) string {
	var pgErr *pgconn.PgError
	switch {
	case err == nil:
		return "none"
	case errors.As(err, &pgErr):
		return "sqlstate " + pgErr.Code
	case errors.Is(err, context.DeadlineExceeded):
		return "timeout"
	case errors.Is(err, context.Canceled):
		return "canceled"
	}
	var ne net.Error
	if errors.As(err, &ne) {
		if ne.Timeout() {
			return "network timeout"
		}
		return "network error"
	}
	return "unclassified error"
}
